{
  "description": "Report on automation activity for a month: how many workflow runs there were, how many failed, and which workflows were busiest.",
  "async": true,
  "parameters": {
    "type": "object",
    "properties": {
      "month": {
        "type": "string",
        "description": "The month to report on, as YYYY-MM. Work it out from what the user said, e.g. 'July' or 'last month'."
      }
    },
    "required": [
      "month"
    ]
  }
}

parameters.jsCode:
const body = $input.first().json.body || {};
const raw = String(body.month || '').trim();
const m = raw.match(/^(\d{4})-(\d{1,2})$/);

const now = new Date();
const year  = m ? Number(m[1]) : now.getFullYear();
const month = m ? Number(m[2]) - 1 : now.getMonth();

const start = new Date(year, month, 1);
const end = new Date(year, month + 1, 1);
const label = start.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });

return [{ json: {
  month: raw || label, label,
  from: start.toISOString(), to: end.toISOString(),
  taskId: body.__task_id, callbackUrl: body.__callback_url,
} }];

const meta = $('Month range').first().json;
const from = new Date(meta.from), to = new Date(meta.to);

const executions = ($('Executions').first().json.data || [])
  .filter(e => { const t = new Date(e.startedAt); return t >= from && t < to; });

const names = {};
for (const w of ($('Workflows').first().json.data || [])) names[w.id] = w.name;

const failed = executions.filter(e => e.status !== 'success').length;

const perWorkflow = {};
for (const e of executions) {
  const key = names[e.workflowId] || e.workflowId;
  perWorkflow[key] = (perWorkflow[key] || 0) + 1;
}
const busiest = Object.entries(perWorkflow).sort((a, b) => b[1] - a[1]).slice(0, 3);

const durations = executions
  .filter(e => e.stoppedAt)
  .map(e => (new Date(e.stoppedAt) - new Date(e.startedAt)) / 1000);
const avg = durations.length
  ? (durations.reduce((a, b) => a + b, 0) / durations.length).toFixed(1)
  : null;

let message;
if (!executions.length) {
  message = `No workflow runs recorded in ${meta.label}.`;
} else {
  const parts = [`${executions.length} workflow runs in ${meta.label}`];
  parts.push(failed ? `${failed} failed` : 'none failed');
  if (busiest.length) parts.push(`busiest was ${busiest[0][0]} with ${busiest[0][1]}`);
  if (avg) parts.push(`averaging ${avg} seconds each`);
  message = parts.join(', ') + '.';
}

return [{ json: { result: { message, month: meta.label, total: executions.length,
                            failed, busiest, averageSeconds: avg },
                  callbackUrl: meta.callbackUrl } }];
